function collarCard(kind){const is4g=kind==='4g'; const title=state.lang==='en'?(is4g?'DeepPet 4G + GPS':'DeepPet Bluetooth Health'):(state.lang==='ko'?(is4g?'DeepPet 4G + GPS':'DeepPet 블루투스 건강형'):(is4g?'DeepPet 4G + GPS':'DeepPet 藍牙健康版')); const desc=state.lang==='en'?(is4g?'Live location, geofence and safety alerts':'Daily health sensing and nearby sync only'):(state.lang==='ko'?(is4g?'위치, 전자 울타리, 안전 알림 지원':'건강 측정과 근거리 동기화 전용'):(is4g?'定位、電子圍欄與安全通知':'日常健康感測與近距離同步')); return `<button class="collar-option ${state.connectChoice===kind?'active':''}" data-action="pick-collar" data-type="${kind}"><img src="${is4g?COLLARS.g4:COLLARS.bt}" alt="${esc(title)}"/><div class="grow"><div class="strong md">${title}</div><div class="subtitle">${desc}</div></div><span class="pill ${is4g?'purple':'ok'}">${is4g?'4G':'BT'}</span></button>`}
