function dpLoadDevice(index){const d=state.devicesByPet?.[String(index)];state.connected=!!d?.connected;state.deviceType=d?.deviceType||null;state.connectedName=d?.connectedName||'';state.connectedId=d?.connectedId||'';state.gpsEnabled=!!d?.gpsEnabled&&d?.deviceType==='4g';state.geofenceEnabled=!!d?.geofenceEnabled&&state.gpsEnabled;}
