function commitAvatarPhoto(){
 if(!avatarDraft?.src||avatarDraft.petIndex!==state.dog){toast(label3('請先選取照片','Choose a photo first','먼저 사진을 선택해 주세요'));return;}
 const key=String(state.dog),before=state.petOverrides?.[key],next={...(before||{}),photo:avatarDraft.src};
 state.petOverrides??={};state.petOverrides[key]=next;
 try{localStorage.setItem('deeppet-v36-local',JSON.stringify((({modal,tab,detail,chartPoint,...v})=>v)(state)));}
 catch(err){if(before)state.petOverrides[key]=before;else delete state.petOverrides[key];toast(label3('儲存空間不足，照片未更換；請清理瀏覽器空間後重試','Browser storage is full. The old photo was kept.','브라우저 저장 공간이 부족합니다. 기존 사진을 유지했습니다.'));return;}
 avatarDraft=null;closeModal();render();toast(label3('寵物照片已更新並儲存在此瀏覽器','Pet photo saved in this browser','반려동물 사진이 브라우저에 저장되었습니다'));
}
function openModal(name){if(name==='avatar-choice')avatarDraft=null;state.modal=name;renderModal();if(name==='live-heart'||name==='live-breath')mountLiveWaves();}
